import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/ApproximationBySuperpositionsOfASigmoidalFunction.html","title":"ApproximationBySuperpositionsOfASigmoidalFunction","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.98,"words":295},"filePathRelative":"ApproximationBySuperpositionsOfASigmoidalFunction.md"}`),a={name:`ApproximationBySuperpositionsOfASigmoidalFunction.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="approximationbysuperpositionsofasigmoidalfunction" tabindex="-1"><a class="header-anchor" href="#approximationbysuperpositionsofasigmoidalfunction"><span>ApproximationBySuperpositionsOfASigmoidalFunction</span></a></h1><p><a href="./論文.html">論文</a>, <a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a></p><p><a href="https://scholar.google.com/scholar?oi=bibs&amp;hl=ja&amp;cluster=7998114008152383322" target="_blank" rel="noopener noreferrer">Cybenko: Approximation by superpositions of a sigmoidal... - Google Scholar</a></p><p>Universal Approximation Theoremの論文 日本語だと普遍性定理か。</p><p>superpositionは重ね合わせだそうで。</p><p>ヒルベルトの13番目のプログラムでKolmogorovがすべてのn変数連続関数は1変数の関数の有限の重ね合わせで表せる、みたいな事が言及されているな。 これか？</p><p><a href="https://en.wikipedia.org/wiki/Kolmogorov%E2%80%93Arnold_representation_theorem" target="_blank" rel="noopener noreferrer">Kolmogorov–Arnold representation theorem - Wikipedia</a></p><p>Rieszの表現定理とか昔やった気がするが何も覚えてないな。</p><p>と数学のフォルダを漁っていたら、買ったまま積ん読だった以下がでてきた。</p><p><a href="https://amzn.to/4w09aiD" target="_blank" rel="noopener noreferrer">amazon: 関数解析 共立数学講座</a></p><p>いい機会なのでこれの最初の方でも読んでみるかなぁ。Rieszの定理は8章だ…</p><h2 id="証明のあらすじ" tabindex="-1"><a class="header-anchor" href="#証明のあらすじ"><span>証明のあらすじ</span></a></h2><p>大まかにあらすじくらいは理解した。</p><p><strong>Discriminatory</strong></p><p>どんなyやθを持ってきても定義の積分が0になる　＝＞ 測度0 を言えるシグマ。</p><p><strong>証明のあらすじ</strong></p><p>Gの形でシグマの線形和を作って、これが稠密である事を証明する。 あらすじとしては稠密でないなら分離するような汎関数が作れて、これがdiscriminatoryの仮定に矛盾する、という話と、 シグモイド関数がdiscriminatoryだ、という二段構えの証明。</p><p>後者はシグモイド関数のパラメータの所に極端なものをいろいろ入れる事で非ゼロ測度があるなら切り出す事が出来るという感じ。</p><p><strong>証明から受ける印象</strong></p><p>これは級数の誤差が減っていく、系の証明では無いので、Nを大きくしていくと誤差が減っていくという事は言えない。 だから例えば誤差を0.1以下にしたい、みたいな時にNをどんどん大きくしていくとだんだんと小さくなって目的の誤差の範囲に抑えられたら操作をやめる、 みたいな事を出来るとは言っていない。</p><p>あくまでそういうGが存在する、と言っているだけ。</p><p>だから実用的には2層のニューラルネットでもノードが多ければ任意の連続関数を近似出来る、という言い方は誤解がある気がする。 どこかにはそういうニューラルネットが存在する、といっているだけ。 Nを増やせば誤差が減っていくという事を言っていないので、適当な所で妥協する余地が無い。</p><p>テイラー展開みたいにだんだんと誤差が減っていくという事が言えれば任意の連続関数をノードを増やせば近似出来ると言ってしまえると思うんだが。</p>`,23)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};